cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

template <int Threads, int PVec, int CoPerBlock, int CinChunk, int MAXK>
__global__ void convT3d_kernel(
    const float* __restrict__ X,
    const float* __restrict__ W,
    const float* __restrict__ Bias,
    float* __restrict__ Y,
    int N, int Cin, int D, int H, int Win,
    int Cout, int CoutPerGroup, int CinPerGroup, int groups,
    int K, int Kvol,
    int stride, int padding, int output_padding,
    int Dout, int Hout, int Wout)
{
  extern __shared__ unsigned char smem_raw[];
  float* sW_ptr = reinterpret_cast<float*>(smem_raw);

  const int n       = blockIdx.z;
  const int co_tile = blockIdx.y;
  const int co_base = co_tile * CoPerBlock;

  const int P_total = Dout * Hout * Wout;
  const int PTile   = Threads * PVec;
  const int p_block = blockIdx.x * PTile;
  const int tid     = threadIdx.x;

  // Group info (assumes CoPerBlock tile does not cross a group boundary)
  int og        = co_base / CoutPerGroup;
  int ci_start  = og * CinPerGroup;
  int ci_end    = ci_start + CinPerGroup;

  int64_t sXn = (int64_t)Cin * D * H * Win;
  int64_t sYn = (int64_t)Cout * Dout * Hout * Wout;

  auto mX = make_tensor(make_gmem_ptr(X + (int64_t)n * sXn),
                         make_shape(Cin, D, H, Win),
                         make_stride((int64_t)D * H * Win, (int64_t)H * Win, (int64_t)Win, (int64_t)1));

  auto mY = make_tensor(make_gmem_ptr(Y + (int64_t)n * sYn),
                         make_shape(Cout, Dout, Hout, Wout),
                         make_stride((int64_t)Dout * Hout * Wout, (int64_t)Hout * Wout, (int64_t)Wout, (int64_t)1));

  auto mW = make_tensor(make_gmem_ptr(W),
                         make_shape(Cin, CoutPerGroup, Kvol),
                         make_stride((int64_t)CoutPerGroup * Kvol, (int64_t)Kvol, (int64_t)1));

  auto sW = make_tensor(make_smem_ptr(sW_ptr),
                         make_shape(CinChunk, CoPerBlock, Kvol),
                         make_stride(CoPerBlock * Kvol, Kvol, 1));

  int od_arr[PVec], oh_arr[PVec], ow_arr[PVec];
  int kd_list[PVec][MAXK], id_list[PVec][MAXK], cnt_d[PVec];
  int kh_list[PVec][MAXK], ih_list[PVec][MAXK], cnt_h[PVec];
  int kw_list[PVec][MAXK], iw_list[PVec][MAXK], cnt_w[PVec];
  bool valid_p[PVec];

  #pragma unroll
  for (int i = 0; i < PVec; ++i) {
    int p = p_block + tid + i * Threads;
    valid_p[i] = (p < P_total);
    cnt_d[i] = 0; cnt_h[i] = 0; cnt_w[i] = 0;
    if (!valid_p[i]) continue;

    int od  = p / (Hout * Wout);
    int rem = p - od * (Hout * Wout);
    int oh  = rem / Wout;
    int ow  = rem - oh * Wout;
    od_arr[i] = od; oh_arr[i] = oh; ow_arr[i] = ow;

    for (int kd = 0; kd < K; ++kd) {
      int num = od + padding - kd;
      if (num % stride != 0) continue;
      int id = num / stride;
      if (id < 0 || id >= D) continue;
      kd_list[i][cnt_d[i]] = kd;
      id_list[i][cnt_d[i]] = id;
      cnt_d[i]++;
    }
    for (int kh = 0; kh < K; ++kh) {
      int num = oh + padding - kh;
      if (num % stride != 0) continue;
      int ih = num / stride;
      if (ih < 0 || ih >= H) continue;
      kh_list[i][cnt_h[i]] = kh;
      ih_list[i][cnt_h[i]] = ih;
      cnt_h[i]++;
    }
    for (int kw = 0; kw < K; ++kw) {
      int num = ow + padding - kw;
      if (num % stride != 0) continue;
      int iw = num / stride;
      if (iw < 0 || iw >= Win) continue;
      kw_list[i][cnt_w[i]] = kw;
      iw_list[i][cnt_w[i]] = iw;
      cnt_w[i]++;
    }
  }

  float acc[CoPerBlock][PVec];
  #pragma unroll
  for (int co = 0; co < CoPerBlock; ++co) {
    int co_global = co_base + co;
    float bval = 0.0f;
    if (Bias != nullptr && co_global < Cout) bval = Bias[co_global];
    #pragma unroll
    for (int i = 0; i < PVec; ++i) acc[co][i] = bval;
  }

  for (int c0 = ci_start; c0 < ci_end; c0 += CinChunk) {
    int total = CinChunk * CoPerBlock * Kvol;
    for (int t = tid; t < total; t += Threads) {
      int cc  = t / (CoPerBlock * Kvol);
      int rem = t - cc * (CoPerBlock * Kvol);
      int co   = rem / Kvol;
      int kidx = rem - co * Kvol;
      int ci = c0 + cc;
      int co_global = co_base + co;
      float wval = 0.0f;
      if (ci < ci_end && co_global < Cout) {
        int co_local = co_global - og * CoutPerGroup;
        wval = mW(ci, co_local, kidx);
      }
      sW(cc, co, kidx) = wval;
    }
    __syncthreads();

    #pragma unroll
    for (int cc = 0; cc < CinChunk; ++cc) {
      int ci = c0 + cc;
      if (ci >= ci_end) continue;

      #pragma unroll
      for (int i = 0; i < PVec; ++i) {
        if (!valid_p[i]) continue;
        for (int di = 0; di < cnt_d[i]; ++di) {
          int id = id_list[i][di];
          int kd = kd_list[i][di];
          for (int hi = 0; hi < cnt_h[i]; ++hi) {
            int ih = ih_list[i][hi];
            int kh = kh_list[i][hi];
            for (int wi = 0; wi < cnt_w[i]; ++wi) {
              int iw = iw_list[i][wi];
              int kw = kw_list[i][wi];
              int kidx = (kd * K + kh) * K + kw;
              float xval = mX(ci, id, ih, iw);
              #pragma unroll
              for (int co = 0; co < CoPerBlock; ++co) {
                acc[co][i] += xval * sW(cc, co, kidx);
              }
            }
          }
        }
      }
    }
    __syncthreads();
  }

  #pragma unroll
  for (int co = 0; co < CoPerBlock; ++co) {
    int co_global = co_base + co;
    if (co_global >= Cout) continue;
    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      if (!valid_p[i]) continue;
      mY(co_global, od_arr[i], oh_arr[i], ow_arr[i]) = acc[co][i];
    }
  }
}

torch::Tensor conv_transpose3d_forward(torch::Tensor x,
                                        torch::Tensor weight,
                                        c10::optional<torch::Tensor> bias,
                                        int64_t stride,
                                        int64_t padding,
                                        int64_t output_padding,
                                        int64_t groups) {
  TORCH_CHECK(x.is_cuda() && weight.is_cuda(), "x and weight must be CUDA tensors");
  TORCH_CHECK(x.scalar_type() == at::kFloat && weight.scalar_type() == at::kFloat,
              "only float32 supported");
  TORCH_CHECK(x.dim() == 5 && weight.dim() == 5, "x and weight must be 5D");

  auto x_c = x.contiguous();
  auto w_c = weight.contiguous();

  int N   = (int)x_c.size(0);
  int Cin = (int)x_c.size(1);
  int D   = (int)x_c.size(2);
  int H   = (int)x_c.size(3);
  int Win = (int)x_c.size(4);

  TORCH_CHECK((int)w_c.size(0) == Cin, "weight in-channels mismatch");
  int CoutPerGroup = (int)w_c.size(1);
  int K = (int)w_c.size(2);
  TORCH_CHECK((int)w_c.size(3) == K && (int)w_c.size(4) == K, "kernel must be cubic");
  TORCH_CHECK(K <= 11, "kernel size too large for this implementation");

  int Cout        = CoutPerGroup * (int)groups;
  int CinPerGroup = Cin / (int)groups;

  int Dout = (D - 1) * (int)stride - 2 * (int)padding + K + (int)output_padding;
  int Hout = (H - 1) * (int)stride - 2 * (int)padding + K + (int)output_padding;
  int Wout = (Win - 1) * (int)stride - 2 * (int)padding + K + (int)output_padding;
  TORCH_CHECK(Dout > 0 && Hout > 0 && Wout > 0, "invalid computed output size");

  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (bias.has_value() && bias.value().defined()) {
    b_c = bias.value().contiguous();
    TORCH_CHECK(b_c.scalar_type() == at::kFloat, "bias must be float32");
    b_ptr = b_c.data_ptr<float>();
  }

  auto y = torch::empty({N, Cout, Dout, Hout, Wout}, x.options());

  constexpr int Threads   = 128;
  constexpr int PVec      = 2;
  constexpr int CoPerBlock= 4;
  constexpr int CinChunk  = 8;
  constexpr int MAXK      = 11;

  int Kvol    = K * K * K;
  int P_total = Dout * Hout * Wout;
  int PTile   = Threads * PVec;

  dim3 block(Threads);
  dim3 grid(
      (unsigned)((P_total + PTile - 1) / PTile),
      (unsigned)((Cout + CoPerBlock - 1) / CoPerBlock),
      (unsigned)N
  );

  size_t smem_size = (size_t)CinChunk * CoPerBlock * Kvol * sizeof(float);

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  convT3d_kernel<Threads, PVec, CoPerBlock, CinChunk, MAXK><<<grid, block, smem_size, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      N, Cin, D, H, Win,
      Cout, CoutPerGroup, CinPerGroup, (int)groups,
      K, Kvol,
      (int)stride, (int)padding, (int)output_padding,
      Dout, Hout, Wout
  );

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "convT3d_kernel launch failed: ", cudaGetErrorString(err));

  return y;
}
