import torch
import torch.nn as nn

from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64


PTX_SOURCE = r"""
.version 8.7
.target sm_89
.address_size 64

// Transposed 3D convolution.
// One thread computes one output element (n, co, od, oh, ow), grid-stride
// looped over the full output volume. For every (ci, kd, kh, kw) that maps
// back to a valid input location the contribution is accumulated.
//
// X : (N, Cin, D, H, Win)                       contiguous
// W : (Cin, CoutPerGroup, K, K, K)               contiguous
// B : (Cout)                                    contiguous (optional)
// Y : (N, Cout, Dout, Hout, Wout)                contiguous
.visible .entry convT3d_kernel(
    .param .u64 param_X,
    .param .u64 param_W,
    .param .u64 param_B,
    .param .u64 param_Y,
    .param .u32 param_N,
    .param .u32 param_Cin,
    .param .u32 param_D,
    .param .u32 param_H,
    .param .u32 param_Win,
    .param .u32 param_Cout,
    .param .u32 param_CoutPerGroup,
    .param .u32 param_CinPerGroup,
    .param .u32 param_K,
    .param .u32 param_stride,
    .param .u32 param_padding,
    .param .u32 param_Dout,
    .param .u32 param_Hout,
    .param .u32 param_Wout,
    .param .u32 param_has_bias
)
{
    .reg .pred %p<18>;
    .reg .b32  %r<51>;
    .reg .b64  %rd<16>;
    .reg .f32  %f<3>;

    ld.param.u64 %rd0, [param_X];
    cvta.to.global.u64 %rd1, %rd0;
    ld.param.u64 %rd2, [param_W];
    cvta.to.global.u64 %rd3, %rd2;
    ld.param.u64 %rd4, [param_B];
    cvta.to.global.u64 %rd5, %rd4;
    ld.param.u64 %rd6, [param_Y];
    cvta.to.global.u64 %rd7, %rd6;

    ld.param.u32 %r0,  [param_N];
    ld.param.u32 %r1,  [param_Cin];
    ld.param.u32 %r2,  [param_D];
    ld.param.u32 %r3,  [param_H];
    ld.param.u32 %r4,  [param_Win];
    ld.param.u32 %r5,  [param_Cout];
    ld.param.u32 %r6,  [param_CoutPerGroup];
    ld.param.u32 %r7,  [param_CinPerGroup];
    ld.param.u32 %r8,  [param_K];
    ld.param.u32 %r9,  [param_stride];
    ld.param.u32 %r10, [param_padding];
    ld.param.u32 %r11, [param_Dout];
    ld.param.u32 %r12, [param_Hout];
    ld.param.u32 %r13, [param_Wout];
    ld.param.u32 %r14, [param_has_bias];

    // total = N * Cout * Dout * Hout * Wout
    mul.lo.s32 %r15, %r11, %r12;
    mul.lo.s32 %r16, %r15, %r13;
    mul.lo.s32 %r17, %r16, %r5;
    mul.lo.s32 %r18, %r17, %r0;

    mov.u32 %r19, %tid.x;
    mov.u32 %r20, %ctaid.x;
    mov.u32 %r21, %ntid.x;
    mad.lo.s32 %r22, %r20, %r21, %r19;   // idx

    mov.u32 %r23, %nctaid.x;
    mul.lo.s32 %r24, %r23, %r21;         // gridStride

LOOP_START:
    setp.ge.s32 %p1, %r22, %r18;
    @%p1 bra LOOP_END;

    // decode idx -> ow, oh, od, co, n  (Y is (N,Cout,Dout,Hout,Wout))
    rem.s32 %r25, %r22, %r13;   // ow
    div.s32 %r26, %r22, %r13;
    rem.s32 %r27, %r26, %r12;   // oh
    div.s32 %r26, %r26, %r12;
    rem.s32 %r28, %r26, %r11;   // od
    div.s32 %r26, %r26, %r11;
    rem.s32 %r29, %r26, %r5;    // co
    div.s32 %r30, %r26, %r5;    // n

    div.s32 %r31, %r29, %r6;    // og = co / CoutPerGroup
    mul.lo.s32 %r32, %r31, %r6;
    sub.s32 %r33, %r29, %r32;   // co_local

    mul.lo.s32 %r34, %r31, %r7; // ci_start
    add.s32 %r35, %r34, %r7;    // ci_end

    mov.f32 %f0, 0f00000000;
    setp.eq.s32 %p0, %r14, 0;
    @%p0 bra BIAS_DONE;
    mul.wide.s32 %rd14, %r29, 4;
    add.s64 %rd15, %rd5, %rd14;
    ld.global.f32 %f0, [%rd15];
BIAS_DONE:

    mov.s32 %r36, %r34;         // ci = ci_start
CI_LOOP:
    setp.ge.s32 %p2, %r36, %r35;
    @%p2 bra CI_LOOP_END;

    mov.s32 %r37, 0;            // kd
KD_LOOP:
    setp.ge.s32 %p3, %r37, %r8;
    @%p3 bra KD_LOOP_END;

    sub.s32 %r38, %r28, %r37;
    add.s32 %r38, %r38, %r10;   // num_d = od + padding - kd
    rem.s32 %r39, %r38, %r9;
    setp.ne.s32 %p4, %r39, 0;
    @%p4 bra KD_CONTINUE;
    div.s32 %r40, %r38, %r9;    // id
    setp.lt.s32 %p5, %r40, 0;
    setp.ge.s32 %p6, %r40, %r2;
    or.pred  %p7, %p5, %p6;
    @%p7 bra KD_CONTINUE;

    mov.s32 %r41, 0;            // kh
KH_LOOP:
    setp.ge.s32 %p8, %r41, %r8;
    @%p8 bra KH_LOOP_END;

    sub.s32 %r42, %r27, %r41;
    add.s32 %r42, %r42, %r10;   // num_h = oh + padding - kh
    rem.s32 %r43, %r42, %r9;
    setp.ne.s32 %p9, %r43, 0;
    @%p9 bra KH_CONTINUE;
    div.s32 %r44, %r42, %r9;    // ih
    setp.lt.s32 %p10, %r44, 0;
    setp.ge.s32 %p11, %r44, %r3;
    or.pred  %p12, %p10, %p11;
    @%p12 bra KH_CONTINUE;

    mov.s32 %r45, 0;            // kw
KW_LOOP:
    setp.ge.s32 %p13, %r45, %r8;
    @%p13 bra KW_LOOP_END;

    sub.s32 %r46, %r25, %r45;
    add.s32 %r46, %r46, %r10;   // num_w = ow + padding - kw
    rem.s32 %r47, %r46, %r9;
    setp.ne.s32 %p14, %r47, 0;
    @%p14 bra KW_CONTINUE;
    div.s32 %r48, %r46, %r9;    // iw
    setp.lt.s32 %p15, %r48, 0;
    setp.ge.s32 %p16, %r48, %r4;
    or.pred  %p17, %p15, %p16;
    @%p17 bra KW_CONTINUE;

    // x_idx = ((n*Cin + ci)*D + id)*H + ih)*Win + iw
    mad.lo.s32 %r49, %r30, %r1, %r36;
    mad.lo.s32 %r49, %r49, %r2, %r40;
    mad.lo.s32 %r49, %r49, %r3, %r44;
    mad.lo.s32 %r49, %r49, %r4, %r48;
    mul.wide.s32 %rd8, %r49, 4;
    add.s64 %rd9, %rd1, %rd8;
    ld.global.f32 %f1, [%rd9];

    // w_idx = ((ci*CoutPerGroup + co_local)*K + kd)*K + kh)*K + kw
    mad.lo.s32 %r50, %r36, %r6, %r33;
    mad.lo.s32 %r50, %r50, %r8, %r37;
    mad.lo.s32 %r50, %r50, %r8, %r41;
    mad.lo.s32 %r50, %r50, %r8, %r45;
    mul.wide.s32 %rd10, %r50, 4;
    add.s64 %rd11, %rd3, %rd10;
    ld.global.f32 %f2, [%rd11];

    fma.rn.f32 %f0, %f1, %f2, %f0;

KW_CONTINUE:
    add.s32 %r45, %r45, 1;
    bra KW_LOOP;
KW_LOOP_END:

KH_CONTINUE:
    add.s32 %r41, %r41, 1;
    bra KH_LOOP;
KH_LOOP_END:

KD_CONTINUE:
    add.s32 %r37, %r37, 1;
    bra KD_LOOP;
KD_LOOP_END:

    add.s32 %r36, %r36, 1;
    bra CI_LOOP;
CI_LOOP_END:

    mul.wide.s32 %rd12, %r22, 4;
    add.s64 %rd13, %rd7, %rd12;
    st.global.f32 [%rd13], %f0;

    add.s32 %r22, %r22, %r24;
    bra LOOP_START;

LOOP_END:
    ret;
}
"""


_module = None


def _get_module():
    global _module
    if _module is None:
        _module = PtxModule(PTX_SOURCE)
    return _module


def validate_generated_code():
    """Sanity check that the PTX module exposes the expected kernel entry."""
    module = _get_module()
    fn = module.function("convT3d_kernel")
    assert fn is not None, "convT3d_kernel entry not found in PTX module"
    return fn


class ModelNew(nn.Module):
    """
    Transposed 3D convolution implemented with a hand-written PTX kernel
    launched through cutegen.ptx_runtime.PtxModule. An nn.ConvTranspose3d
    submodule is kept purely for parameter storage / initialization; all
    forward computation runs through the PTX kernel.
    """

    def __init__(self, in_channels: int, out_channels: int, kernel_size: int,
                 stride: int = 1, padding: int = 0, output_padding: int = 0,
                 groups: int = 1, bias: bool = False):
        super().__init__()
        self.conv_transpose3d = nn.ConvTranspose3d(
            in_channels, out_channels,
            kernel_size=(kernel_size, kernel_size, kernel_size),
            stride=stride, padding=padding, output_padding=output_padding,
            groups=groups, bias=bias,
        )
        self.stride = int(stride)
        self.padding = int(padding)
        self.output_padding = int(output_padding)
        self.groups = int(groups)
        self.kernel_size = int(kernel_size)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda, "input must be a CUDA tensor"
        assert x.dtype == torch.float32, "only float32 supported"
        assert x.dim() == 5, "input must be 5D (N, C, D, H, W)"

        x_c = x.contiguous()
        weight = self.conv_transpose3d.weight.contiguous()
        bias = self.conv_transpose3d.bias

        N, Cin, D, H, Win = (int(s) for s in x_c.shape)
        CoutPerGroup = int(weight.shape[1])
        K = int(weight.shape[2])
        Cout = CoutPerGroup * self.groups
        CinPerGroup = Cin // self.groups

        stride = self.stride
        padding = self.padding
        output_padding = self.output_padding

        Dout = (D - 1) * stride - 2 * padding + K + output_padding
        Hout = (H - 1) * stride - 2 * padding + K + output_padding
        Wout = (Win - 1) * stride - 2 * padding + K + output_padding
        assert Dout > 0 and Hout > 0 and Wout > 0, "invalid computed output size"

        y = torch.empty((N, Cout, Dout, Hout, Wout), device=x_c.device, dtype=torch.float32)

        if bias is not None and bias.defined():
            bias_c = bias.contiguous()
            bias_ptr = bias_c.data_ptr()
            has_bias = 1
        else:
            bias_c = None
            bias_ptr = 0
            has_bias = 0

        total = N * Cout * Dout * Hout * Wout
        block_x = 256
        grid_x = max((total + block_x - 1) // block_x, 1)

        module = _get_module()
        fn = module.function("convT3d_kernel")

        stream = torch.cuda.current_stream(device=x_c.device).cuda_stream

        args = [
            u64(x_c.data_ptr()),
            u64(weight.data_ptr()),
            u64(bias_ptr),
            u64(y.data_ptr()),
            i32(N), i32(Cin), i32(D), i32(H), i32(Win),
            i32(Cout), i32(CoutPerGroup), i32(CinPerGroup),
            i32(K), i32(stride), i32(padding),
            i32(Dout), i32(Hout), i32(Wout), i32(has_bias),
        ]

        fn.launch(
            grid=(grid_x, 1, 1),
            block=(block_x, 1, 1),
            shared_mem_bytes=0,
            stream=stream,
            args=args,
        )

        return y
